AssistantMessageToolRequest(name='create', tool_call_id='tooluse_1qFGFDhGbWWnyV2rX741gP', arguments={'file_text': "/* ============================================================================
   Root & Reset
   ========================================================================== */

:root {
  /* Semantic color palette */
  --color-bg-primary: #0f0f0f;
  --color-bg-secondary: #1a1a1a;
  --color-bg-tertiary: #252525;
  --color-bg-highlight: #2d2d2d;

  --color-text-primary: #ffffff;
  --color-text-secondary: #d4d4d4;
  --color-text-tertiary: #a0a0a0;

  --color-accent-primary: #e8b4f9;
  --color-accent-secondary: #d4a5e8;
  --color-accent-dark: #b080cc;

  --color-success: #4ade80;
  --color-warning: #f59e0b;
  --color-error: #ef4444;

  /* Typography */
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
    Ubuntu, Cantarell, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 2.5rem;
  --font-size-4xl: 3rem;

  --line-height-tight: 1.2;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.75;

  --letter-spacing-tight: -0.01em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.05em;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;
  --spacing-4xl: 6rem;

  /* Borders & Radii */
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 1rem;
  --border-radius-full: 9999px;

  --border-width: 1px;
  --border-color: #404040;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.5);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.3);
  --shadow-xl: 0 20px 25px rgba(0, 0, 0, 0.2);

  /* Transitions */
  --transition-fast: 150ms ease-in-out;
  --transition-base: 200ms ease-in-out;
  --transition-slow: 300ms ease-in-out;

  /* Z-index */
  --z-nav: 100;
  --z-modal: 1000;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  color-scheme: dark;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  line-height: var(--line-height-normal);
  font-size: var(--font-size-base);
  font-weight: 400;
  overflow-x: hidden;
}

/* ============================================================================
   Accessibility & Skip Links
   ========================================================================== */

.skip-to-main {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-accent-primary);
  color: var(--color-bg-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  text-decoration: none;
  z-index: var(--z-modal);
  font-weight: 600;
}

.skip-to-main:focus {
  top: 0;
  outline: 3px solid var(--color-accent-dark);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================================
   Typography
   ========================================================================== */

h1,
h2,
h3,
h4,
h5,
h6 {
  font-weight: 600;
  line-height: var(--line-height-tight);
  margin-bottom: var(--spacing-md);
  letter-spacing: var(--letter-spacing-tight);
}

h1 {
  font-size: var(--font-size-4xl);
}

h2 {
  font-size: var(--font-size-3xl);
}

h3 {
  font-size: var(--font-size-xl);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-accent-primary);
  text-decoration: none;
  transition: color var(--transition-base);
  font-weight: 500;
  cursor: pointer;
}

a:hover {
  color: var(--color-accent-secondary);
}

a:focus {
  outline: 2px solid var(--color-accent-primary);
  outline-offset: 2px;
  border-radius: var(--border-radius-sm);
}

/* ============================================================================
   Buttons
   ========================================================================== */

button {
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition-base);
  border: none;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-base);
  font-weight: 500;
}

button:focus {
  outline: 2px solid var(--color-accent-primary);
  outline-offset: 2px;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.cta-button {
  background-color: var(--color-accent-primary);
  color: var(--color-bg-primary);
  padding: var(--spacing-md) var(--spacing-xl);
  font-size: var(--font-size-lg);
  font-weight: 600;
}

.cta-button:hover:not(:disabled) {
  background-color: var(--color-accent-secondary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.cta-button:active:not(:disabled) {
  transform: translateY(0);
}

/* ============================================================================
   Header & Navigation
   ========================================================================== */

.header {
  background-color: var(--color-bg-secondary);
  border-bottom: var(--border-width) solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: var(--z-nav);
  box-shadow: var(--shadow-sm);
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg) var(--spacing-xl);
  gap: var(--spacing-xl);
}

.logo {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  letter-spacing: var(--letter-spacing-wide);
  background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  white-space: nowrap;
  margin: 0;
}

.nav-toggle {
  display: none;
  background: none;
  color: var(--color-text-primary);
  padding: var(--spacing-sm);
  border-radius: var(--border-radius-md);
}

.nav-toggle:hover {
  background-color: var(--color-bg-tertiary);
}

.hamburger {
  display: block;
  width: 24px;
  height: 24px;
  position: relative;
}

.hamburger::before,
.hamburger::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 2px;
  background-color: var(--color-text-primary);
  left: 0;
  transition: all var(--transition-base);
}

.hamburger::before {
  top: 6px;
}

.hamburger::after {
  bottom: 6px;
}

.hamburger {
  background-color: transparent;
}

.hamburger::before {
  box-shadow: 0 8px 0 var(--color-text-primary);
}

.nav-toggle[aria-expanded='true'] .hamburger::before {
  transform: translateY(8px) rotate(45deg);
  box-shadow: 0 0 0 var(--color-text-primary);
}

.nav-toggle[aria-expanded='true'] .hamburger::after {
  transform: translateY(-8px) rotate(-45deg);
}

.nav-primary {
  flex: 1;
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-lg);
  align-items: center;
}

.nav-link {
  color: var(--color-text-secondary);
  transition: color var(--transition-base);
  font-size: var(--font-size-base);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--border-radius-sm);
}

.nav-link:hover {
  color: var(--color-accent-primary);
  background-color: var(--color-bg-highlight);
}

.header-actions {
  display: flex;
  gap: var(--spacing-lg);
  align-items: center;
}

.action-button {
  background: none;
  color: var(--color-text-primary);
  padding: var(--spacing-sm);
  position: relative;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
}

.action-button:hover {
  background-color: var(--color-bg-highlight);
}

.cart-badge {
  position: absolute;
  top: -5px;
  right: -5px;
  background-color: var(--color-accent-primary);
  color: var(--color-bg-primary);
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: 2px 6px;
  border-radius: var(--border-radius-full);
  min-width: 20px;
  text-align: center;
}

/* ============================================================================
   Hero Section
   ========================================================================== */

.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-3xl);
  align-items: center;
  padding: var(--spacing-4xl) var(--spacing-xl);
  max-width: 1400px;
  margin: 0 auto;
  min-height: 500px;
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.hero-content h2 {
  font-size: var(--font-size-4xl);
  margin: 0;
}

.hero-subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  margin: 0;
}

.hero-image {
  width: 100%;
  height: 400px;
  background: linear-gradient(135deg, var(--color-accent-dark), var(--color-accent-primary));
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-xl);
}

/* ============================================================================
   Sections
   ========================================================================== */

.section {
  padding: var(--spacing-3xl) var(--spacing-xl);
  background-color: var(--color-bg-primary);
}

.section:nth-child(even) {
  background-color: var(--color-bg-secondary);
}

.section-container {
  max-width: 1400px;
  margin: 0 auto;
}

.section-title {
  font-size: var(--font-size-3xl);
  margin-bottom: var(--spacing-md);
}

.section-description {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-2xl);
}

/* ============================================================================
   Featured Products Grid
   ========================================================================== */

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-2xl);
}

.product-card {
  background-color: var(--color-bg-highlight);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  border-color: var(--color-accent-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.product-image {
  width: 100%;
  height: 250px;
  background: linear-gradient(135deg, var(--color-bg-highlight), var(--color-bg-tertiary));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-4xl);
  color: var(--color-accent-primary);
  opacity: 0.7;
}

.product-details {
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.product-name {
  font-size: var(--font-size-lg);
  margin: 0;
  font-weight: 600;
}

.product-category {
  font-size: var(--font-size-sm);
  color: var(--color-text-tertiary);
  margin: 0;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: var(--font-size-sm);
}

.stars {
  color: var(--color-warning);
  letter-spacing: 2px;
}

.rating-count {
  color: var(--color-text-tertiary);
}

.product-price {
  display: flex;
  gap: var(--spacing-md);
  align-items: baseline;
}

.price-current {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-accent-primary);
}

.add-to-cart-btn {
  background-color: var(--color-bg-tertiary);
  color: var(--color-text-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  border: var(--border-width) solid var(--color-border-color);
  border-radius: var(--border-radius-md);
  font-weight: 600;
  transition: all var(--transition-base);
  margin-top: auto;
}

.add-to-cart-btn:hover {
  background-color: var(--color-accent-primary);
  color: var(--color-bg-primary);
  border-color: var(--color-accent-primary);
}

/* ============================================================================
   Deals Grid
   ========================================================================== */

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-2xl);
}

.deal-card {
  background: linear-gradient(135deg, var(--color-bg-highlight), var(--color-bg-tertiary));
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  position: relative;
  transition: all var(--transition-base);
}

.deal-card:hover {
  border-color: var(--color-accent-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.deal-badge {
  position: absolute;
  top: var(--spacing-lg);
  right: var(--spacing-lg);
  z-index: 10;
}

.badge-percent {
  background-color: var(--color-error);
  color: var(--color-text-primary);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--border-radius-md);
  font-weight: 700;
  font-size: var(--font-size-lg);
  display: block;
}

.deal-image {
  width: 100%;
  height: 220px;
  background: linear-gradient(135deg, var(--color-accent-dark), var(--color-accent-primary));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-4xl);
  opacity: 0.8;
}

.deal-details {
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.deal-name {
  font-size: var(--font-size-lg);
  margin: 0;
  font-weight: 600;
}

.deal-prices {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

.price-original {
  font-size: var(--font-size-base);
  color: var(--color-text-tertiary);
  text-decoration: line-through;
}

.price-sale {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-success);
}

.price-savings {
  font-size: var(--font-size-sm);
  color: var(--color-success);
  font-weight: 600;
}

.deal-timer {
  background-color: var(--color-bg-secondary);
  padding: var(--spacing-md);
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-sm);
}

.timer-label {
  color: var(--color-text-tertiary);
}

.timer-display {
  color: var(--color-accent-primary);
  font-weight: 700;
  margin-left: var(--spacing-sm);
}

.deal-cta {
  background-color: var(--color-accent-primary);
  color: var(--color-bg-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  font-weight: 600;
  border-radius: var(--border-radius-md);
}

.deal-cta:hover {
  background-color: var(--color-accent-secondary);
  transform: translateY(-2px);
}

/* ============================================================================
   Editorial Section
   ========================================================================== */

.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-2xl);
}

.editorial-card {
  background-color: var(--color-bg-highlight);
  border: var(--border-width) solid var(--border-color);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.editorial-card:hover {
  border-color: var(--color-accent-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.editorial-image {
  width: 100%;
  height: 240px;
  background: linear-gradient(135deg, var(--color-accent-secondary), var(--color-accent-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-4xl);
  opacity: 0.7;
}

.editorial-content {
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.article-category {
  font-size: var(--font-size-xs);
  font-weight: 700;
  color: var(--color-accent-primary);
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wide);
}

.article-title {
  font-size: var(--font-size-xl);
  margin: 0;
  line-height: var(--line-height-tight);
}

.article-excerpt {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: var(--line-height-relaxed);
  margin: 0;
}

.article-date {
  font-size: var(--font-size-sm);
  color: var(--color-text-tertiary);
}

.read-more-link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-weight: 600;
  color: var(--color-accent-primary);
  margin-top: var(--spacing-md);
  width: fit-content;
}

.read-more-link:hover {
  color: var(--color-accent-secondary);
}

/* ============================================================================
   Newsletter Section
   ========================================================================== */

.newsletter {
  background: linear-gradient(135deg, var(--color-accent-dark), var(--color-accent-primary));
  padding: var(--spacing-4xl) var(--spacing-xl);
}

.newsletter-container {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
  color: var(--color-bg-primary);
}

.newsletter-container h2 {
  color: var(--color-bg-primary);
  margin-bottom: var(--spacing-md);
}

.newsletter-container p {
  color: rgba(15, 15, 15, 0.8);
  margin-bottom: var(--spacing-2xl);
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.newsletter-form input {
  padding: var(--spacing-md) var(--spacing-lg);
  border: none;
  border-radius: var(--border-radius-md);
  background-color: rgba(255, 255, 255, 0.95);
  color: var(--color-bg-primary);
  font-size: var(--font-size-base);
  font-family: inherit;
}

.newsletter-form input::placeholder {
  color: var(--color-text-tertiary);
}

.newsletter-form input:focus {
  outline: 2px solid var(--color-bg-primary);
  outline-offset: 2px;
  background-color: #ffffff;
}

.newsletter-submit {
  background-color: var(--color-bg-primary);
  color: var(--color-accent-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  font-weight: 700;
  font-size: var(--font-size-base);
}

.newsletter-submit:hover {
  background-color: var(--color-bg-secondary);
}

.form-help-text {
  font-size: var(--font-size-xs);
  color: rgba(15, 15, 15, 0.7);
  margin: 0;
}

/* ============================================================================
   Footer
   ========================================================================== */

.footer {
  background-color: var(--color-bg-secondary);
  border-top: var(--border-width) solid var(--border-color);
  padding: var(--spacing-3xl) var(--spacing-xl);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-2xl);
  max-width: 1400px;
  margin: 0 auto;
  margin-bottom: var(--spacing-3xl);
}

.footer-section h3 {
  font-size: var(--font-size-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-section ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.footer-section a {
  font-size: var(--font-size-base);
  font-weight: 400;
  color: var(--color-text-secondary);
  transition: color var(--transition-base);
}

.footer-section a:hover {
  color: var(--color-accent-primary);
}

.footer-bottom {
  max-width: 1400px;
  margin: 0 auto;
  border-top: var(--border-width) solid var(--border-color);
  padding-top: var(--spacing-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}

.footer-bottom p {
  font-size: var(--font-size-sm);
  color: var(--color-text-tertiary);
  margin: 0;
}

.footer-legal {
  list-style: none;
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: var(--font-size-sm);
  font-weight: 400;
  color: var(--color-text-tertiary);
}

/* ============================================================================
   Responsive Design
   ========================================================================== */

@media (max-width: 768px) {
  .header-content {
    padding: var(--spacing-md) var(--spacing-lg);
    gap: var(--spacing-md);
  }

  .logo {
    font-size: var(--font-size-xl);
  }

  .nav-toggle {
    display: block;
  }

  .nav-menu {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background-color: var(--color-bg-secondary);
    border-bottom: var(--border-width) solid var(--border-color);
    flex-direction: column;
    gap: 0;
    padding: var(--spacing-lg);
    list-style: none;
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
  }

  .nav-toggle[aria-expanded='true'] ~ .nav-menu {
    max-height: 400px;
  }

  .nav-link {
    padding: var(--spacing-md) 0;
    display: block;
  }

  .hero {
    grid-template-columns: 1fr;
    gap: var(--spacing-2xl);
    padding: var(--spacing-2xl) var(--spacing-lg);
    min-height: auto;
  }

  .hero-content h2 {
    font-size: var(--font-size-2xl);
  }

  .hero-image {
    height: 300px;
