    setInterval(() => updateTimer(display), 1000);
  });
}

function updateTimer(timerDisplay) {
  // In a real app, this would calculate remaining time from server time
  // For demo, we'll just maintain the display
  const timeString = timerDisplay.textContent;
  const match = timeString.match(/(\d+)d\s+(\d+)h\s+(\d+)m/);

  if (!match) return;

  let days = parseInt(match[1]);
  let hours = parseInt(match[2]);
  let minutes = parseInt(match[3]);

