  gap: var(--spacing-lg);
  align-items: center;
}

.action-button {
  background: none;
  color: var(--color-text-primary);
  padding: var(--spacing-sm);
  position: relative;
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-lg);
}

.action-button:hover {
  background-color: var(--color-bg-highlight);
}

.cart-badge {
  position: absolute;
  top: -5px;
  right: -5px;
  background-color: var(--color-accent-primary);
