  padding: 2px 6px;
  border-radius: var(--border-radius-full);
  min-width: 20px;
  text-align: center;
}

/* ============================================================================
   Hero Section
   ========================================================================== */

.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
