+/**
+ * LuxeMart Ecommerce Home Page
+ * Interactivity and state management
+ */
+
+// ============================================================================
+// Navigation Toggle
+// ============================================================================
+
+function initializeNavigation() {
+  const navToggle = document.querySelector('.nav-toggle');
+  const navMenu = document.getElementById('nav-menu');
+
+  if (!navToggle) return;
+
+  navToggle.addEventListener('click', () => {
+    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
+    navToggle.setAttribute('aria-expanded', !isExpanded);
+  });
+
+  // Close menu when a link is clicked
+  const navLinks = navMenu.querySelectorAll('a');
+  navLinks.forEach((link) => {
+    link.addEventListener('click', () => {
+      navToggle.setAttribute('aria-expanded', 'false');
+    });
+  });
+
+  // Close menu when clicking outside
+  document.addEventListener('click', (event) => {
+    if (!event.target.closest('.nav-primary')) {
+      navToggle.setAttribute('aria-expanded', 'false');
+    }
+  });
+
+  // Close menu on Escape key
+  document.addEventListener('keydown', (event) => {
+    if (event.key === 'Escape') {
+      navToggle.setAttribute('aria-expanded', 'false');
+    }
+  });
+}
+
+// ============================================================================
+// Add to Cart Functionality
+// ============================================================================
+
+function initializeCart() {
+  const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
+  let cartCount = 2; // Initial count from badge
+
+  addToCartButtons.forEach((button) => {
+    button.addEventListener('click', (event) => {
+      event.preventDefault();
+
+      // Get product details
+      const productCard = button.closest('.product-card');
+      const productName = productCard
+        .querySelector('.product-name')
+        .textContent;
+
+      // Update cart count
+      cartCount++;
+      updateCartBadge(cartCount);
+
+      // Show feedback
+      const originalText = button.textContent;
+      button.textContent = 'Added ✓';
+      button.disabled = true;
+
+      setTimeout(() => {
+        button.textContent = originalText;
+        button.disabled = false;
+      }, 2000);
+
+      // Announce to screen readers
+      announceToScreenReader(`${productName} added to cart`);
+    });
+  });
+}
+
+function updateCartBadge(count) {
+  const cartBadge = document.querySelector('.cart-badge');
+  if (cartBadge) {
+    cartBadge.textContent = count;
+    cartBadge.setAttribute('aria-label', `${count} items in cart`);
+  }
+}
+
+// ============================================================================
+// Newsletter Form
+// ============================================================================
+
+function initializeNewsletter() {
+  const form = document.querySelector('.newsletter-form');
+  if (!form) return;
+
+  form.addEventListener('submit', (event) => {
+    event.preventDefault();
+
+    const emailInput = form.querySelector('input[type="email"]');
+    const email = emailInput.value.trim();
+
+    if (!email) {
+      announceToScreenReader('Please enter a valid email address');
+      return;
+    }
+
+    // Simulate submission
+    const submitButton = form.querySelector('button[type="submit"]');
+    const originalText = submitButton.textContent;
+    submitButton.textContent = 'Subscribed ✓';
+    submitButton.disabled = true;
+
+    setTimeout(() => {
+      submitButton.textContent = originalText;
+      submitButton.disabled = false;
+      emailInput.value = '';
+      announceToScreenReader('Successfully subscribed to newsletter');
+    }, 2000);
+  });
+}
+
+// ============================================================================
+// Deal Timer Updates
+// ============================================================================
+
+function initializeDealTimers() {
+  const timerDisplays = document.querySelectorAll('.timer-display');
+
+  timerDisplays.forEach((display) => {
+    // Parse initial time and update every second
+    updateTimer(display);
+    setInterval(() => updateTimer(display), 1000);
+  });
+}
+
+function updateTimer(timerDisplay) {
+  // In a real app, this would calculate remaining time from server time
+  // For demo, we'll just maintain the display
+  const timeString = timerDisplay.textContent;
+  const match = timeString.match(/(\d+)d\s+(\d+)h\s+(\d+)m/);
+
+  if (!match) return;
+
+  let days = parseInt(match[1]);
+  let hours = parseInt(match[2]);
+  let minutes = parseInt(match[3]);
+
+  // Decrement minutes
+  minutes--;
+
+  if (minutes < 0) {
+    minutes = 59;
+    hours--;
+
+    if (hours < 0) {
+      hours = 23;
+      days--;
+    }
+  }
+
+  if (days >= 0) {
+    timerDisplay.textContent = `${days}d ${hours}h ${minutes}m`;
+
+    // Announce time changes to screen readers (only every 5 minutes to avoid spam)
+    if (minutes % 5 === 0 && minutes === 0) {
+      const parent = timerDisplay.closest('.deal-card');
+      const dealName = parent
+        .querySelector('.deal-name')
+        ?.textContent || 'Deal';
+      announceToScreenReader(
+        `${dealName} deal ending in ${days} days ${hours} hours`
+      );
+    }
+  }
+}
+
+// ============================================================================
+// Deal CTA Buttons
+// ============================================================================
+
+function initializeDealCTAs() {
+  const dealCtaButtons = document.querySelectorAll('.deal-cta');
+
+  dealCtaButtons.forEach((button) => {
+    button.addEventListener('click', (event) => {
+      event.preventDefault();
+
+      const dealCard = button.closest('.deal-card');
+      const dealName = dealCard.querySelector('.deal-name').textContent;
+
+      // Show feedback
+      const originalText = button.textContent;
+      button.textContent = 'Viewing ✓';
+      button.disabled = true;
+
+      setTimeout(() => {
+        button.textContent = originalText;
+        button.disabled = false;
+      }, 1500);
+
+      announceToScreenReader(`Viewing ${dealName}`);
+    });
+  });
+}
+
+// ============================================================================
+// Article Read More Links
+// ============================================================================
+
+function initializeArticleLinks() {
+  const readMoreLinks = document.querySelectorAll('.read-more-link');
+
+  readMoreLinks.forEach((link) => {
+    link.addEventListener('click', (event) => {
+      event.preventDefault();
+
+      const article = link.closest('.editorial-card');
+      const articleTitle = article
+        .querySelector('.article-title')
+        .textContent;
+
+      announceToScreenReader(`Opening article: ${articleTitle}`);
+
+      // In a real app, this would navigate to the article
+      setTimeout(() => {
+        alert(`Would navigate to: ${articleTitle}`);
+      }, 200);
+    });
+  });
+}
+
+// ============================================================================
+// Screen Reader Announcements
+// ============================================================================
+
+function announceToScreenReader(message) {
+  // Create or get the live region
+  let liveRegion = document.getElementById('sr-announcer');
+
+  if (!liveRegion) {
+    liveRegion = document.createElement('div');
+    liveRegion.id = 'sr-announcer';
+    liveRegion.setAttribute('aria-live', 'polite');
+    liveRegion.setAttribute('aria-atomic', 'true');
+    liveRegion.className = 'sr-only';
+    document.body.appendChild(liveRegion);
+  }
+
+  liveRegion.textContent = message;
+
+  // Clear after announcement to avoid redundant reads
+  setTimeout(() => {
+    liveRegion.textContent = '';
+  }, 1000);
+}
+
+// ============================================================================
+// Keyboard Navigation Enhancement
+// ============================================================================
+
+function initializeKeyboardNav() {
+  document.addEventListener('keydown', (event) => {
+    // Add keyboard shortcuts here if needed
+    // For example: "/" to focus search, "?" for help, etc.
+  });
+}
+
+// ============================================================================
+// Performance: Lazy Load Product Images (if they were real images)
+// ============================================================================
+
+function initializeLazyLoading() {
+  // In a production app with real images, use Intersection Observer
+  if ('IntersectionObserver' in window) {
+    const images = document.querySelectorAll('[data-lazy-src]');
+
+    const imageObserver = new IntersectionObserver((entries) => {
+      entries.forEach((entry) => {
+        if (entry.isIntersecting) {
+          const img = entry.target;
+          img.src = img.dataset.lazySrc;
+          img.removeAttribute('data-lazy-src');
+          imageObserver.unobserve(img);
+        }
+      });
+    });
+
+    images.forEach((img) => imageObserver.observe(img));
+  }
+}
+
+// ============================================================================
+// Initialization
+// ============================================================================
+
+document.addEventListener('DOMContentLoaded', () => {
+  initializeNavigation();
+  initializeCart();
+  initializeNewsletter();
+  initializeDealTimers();
+  initializeDealCTAs();
+  initializeArticleLinks();
+  initializeKeyboardNav();
+  initializeLazyLoading();
+
+  // Log initialization for debugging (remove in production)
+  console.log('LuxeMart home page initialized');
+});
+
+// ============================================================================
+// Accessibility: Announce page readiness to screen readers
+// ============================================================================
+
+window.addEventListener('load', () => {
+  // Optional: Announce that the page has fully loaded
+  if (document.readyState === 'complete') {
+    console.log('Page fully loaded and ready');
+  }
+});
+
')

